insert into public.phases (id, name, position, is_loop) values
 (1, 'Win and price', 1, false),
 (2, 'Set up in Odoo', 2, false),
 (3, 'Execute', 3, false),
 (4, 'Monthly billing cycle', 4, true);
insert into public.steps (phase_id, position, title, short_label, what, owner, odoo, control, output, money, cadence, basis) values
 (1, 1, 'Estimated cost with details', E'Cost\nestimate', 'Price every BOQ line: Daikin equipment, materials, subcontract labour, overheads and margin, giving the selling price.', 'Technical office / estimation, CFO review', 'Excel estimate (before Odoo)', 'Margin check before the quote goes out. The estimate becomes the project''s original cost budget.', 'Priced BOQ + cost budget', 'Baseline', 'Once', 'Confirmed'),
 (1, 2, 'Customer contract signed', E'Contract\nsigned', 'Agree scope, contract value, payment terms (advance, progress, retention) and the billing basis.', 'GM / Sales manager', 'Signed contract attached to the quotation', 'Contract value and terms match the approved estimate. Clause making issued-but-not-installed materials billable.', 'Signed contract', 'Commitment', 'Once', 'Confirmed'),
 (2, 1, 'Customer contract in Odoo with BOQ', E'Sales order\n+ BOQ', 'Confirm the sales order with every BOQ line (materials and items) and its cost, linked to the project. A variation order is set up as a separate new contract.', 'Technical office', 'Sales order, project and analytic account', 'Sales order total = contract value. Budget by cost type (materials + subcontractor). Budget revisions approved by CFO, then GM.', 'Contract value + cost baseline', 'Baseline', 'Once', 'Confirmed'),
 (2, 2, 'Customer payment in Odoo', E'Customer\npayment', 'Record the advance (down payment) and later collections against the customer and contract.', 'A/R Accountant; collection follow-up by Sales manager', 'Customer payment, reconciled to the contract / invoice', 'Payment matched to the right contract. A/R aging reviewed monthly with the sales manager.', 'Cash in + customer balance', 'Cash in', 'Once, then monthly', 'Confirmed'),
 (3, 1, 'Subcontractor contracts', 'Subcontracts', 'Award installation and labour packages: scope, rates, retention, payment on the 10th of each month.', 'Technical office', 'Purchase order / subcontract agreement per project', 'Subcontract value stays within the subcontractor budget line.', 'Committed subcontractor cost', 'Commitment', 'Once per package', 'Confirmed'),
 (3, 2, 'Issue material from store', E'Material\nissue', 'Issue Daikin units and materials from the company store to the project.', 'Storekeeper, on site engineer''s request', 'Inventory transfer to the project (analytic)', 'Material counts as project cost when issued. Issued-but-not-installed material is billable under the contract.', 'Material cost to date', 'Cost', 'Monthly', 'Confirmed'),
 (4, 1, 'Project progress percentage', 'Progress %', 'Site engineer sends one monthly Excel with % complete per contract and per variation order.', 'Site engineer, CFO makes the final call', 'Excel sheet, feeds the progress invoice', 'Cost-to-cost check: posted (materials + subcontractor) cost / budget. A gap above 10 points means a revised % and an investigation.', 'Approved % complete', 'Control', 'Monthly', 'Confirmed'),
 (4, 2, 'Customer progress invoice', E'Progress\ninvoice', 'Invoice = final % x contract value - revenue already recognized.', 'A/R Accountant drafts, Chief Accountant audits, CFO approves, Chief Accountant posts', 'Progress invoice (APPROVED stage, CFO only)', 'Audited against the engineer''s Excel. Reset to draft only before the customer receives it; after that, a credit note.', 'Revenue + A/R', 'Cash in', 'Monthly', 'Confirmed'),
 (4, 3, 'Subcontractor progress bill', E'Subcontractor\nbill', 'Post the subcontractor''s monthly bill against the project; pay on the 10th.', 'A/P Accountant', 'Vendor bill (draft accrual at month-end if unbilled)', 'Cost counts only when the bill is posted; the draft accrual is ignored in the cost-to-cost check.', 'Subcontractor cost to date + A/P', 'Cost', 'Monthly', 'Confirmed');
